CREATE SCHEMA IF NOT EXISTS wallet_service;
CREATE TYPE wallet_status AS ENUM ('active', 'frozen', 'closed');
CREATE TYPE ledger_status AS ENUM ('pending', 'completed', 'reversed', 'failed');
CREATE TYPE hold_status AS ENUM ('active', 'captured', 'released');
CREATE TYPE withdrawal_status AS ENUM ('requested', 'processing', 'succeeded', 'failed', 'cancelled', 'needs_review');
CREATE TABLE wallets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID UNIQUE, system_key VARCHAR(80) UNIQUE, balance BIGINT NOT NULL DEFAULT 0, reserved_balance BIGINT NOT NULL DEFAULT 0, status wallet_status NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT wallets_balance_nonnegative CHECK (balance >= 0), CONSTRAINT wallets_reserved_valid CHECK (reserved_balance >= 0 AND reserved_balance <= balance), CONSTRAINT wallets_owner_xor_system CHECK ((user_id IS NULL) <> (system_key IS NULL)));
CREATE TABLE wallet_transfers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), operation_id VARCHAR(160) NOT NULL UNIQUE, idempotency_key VARCHAR(200) NOT NULL UNIQUE, kind VARCHAR(40) NOT NULL, total_amount BIGINT NOT NULL CHECK (total_amount > 0), status ledger_status NOT NULL DEFAULT 'completed', metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wallet_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id UUID NOT NULL REFERENCES wallets(id), transfer_id UUID REFERENCES wallet_transfers(id), type VARCHAR(40) NOT NULL, direction VARCHAR(8) NOT NULL CHECK (direction IN ('debit','credit')), amount BIGINT NOT NULL CHECK (amount > 0), status ledger_status NOT NULL DEFAULT 'completed', operation_id VARCHAR(160), idempotency_key VARCHAR(200) UNIQUE, reference_id VARCHAR(160), description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX wallet_transactions_wallet_created_idx ON wallet_transactions(wallet_id, created_at DESC);
CREATE INDEX wallet_transactions_operation_idx ON wallet_transactions(operation_id);
CREATE INDEX wallet_transactions_reference_idx ON wallet_transactions(reference_id);
CREATE FUNCTION reject_wallet_transaction_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'wallet_transactions is append-only'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER wallet_transactions_immutable BEFORE UPDATE OR DELETE ON wallet_transactions FOR EACH ROW EXECUTE FUNCTION reject_wallet_transaction_mutation();
CREATE TABLE withdrawals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, wallet_id UUID NOT NULL REFERENCES wallets(id), bank_account_id UUID NOT NULL, amount BIGINT NOT NULL CHECK (amount > 0), status withdrawal_status NOT NULL DEFAULT 'requested', idempotency_key VARCHAR(200) NOT NULL UNIQUE, payout_reference VARCHAR(160) UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX withdrawals_user_created_idx ON withdrawals(user_id, created_at DESC);
CREATE TABLE wallet_holds (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), wallet_id UUID NOT NULL REFERENCES wallets(id), withdrawal_id UUID NOT NULL UNIQUE REFERENCES withdrawals(id), amount BIGINT NOT NULL CHECK (amount > 0), status hold_status NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX wallet_holds_wallet_status_idx ON wallet_holds(wallet_id, status);
CREATE TABLE outbox_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_type VARCHAR(120) NOT NULL, event_version INTEGER NOT NULL DEFAULT 1, payload JSONB NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'pending', retry_count INTEGER NOT NULL DEFAULT 0, next_retry_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
CREATE INDEX wallet_outbox_pending_idx ON outbox_events(status,next_retry_at);
CREATE TABLE inbox_events (event_id VARCHAR(200) PRIMARY KEY, event_type VARCHAR(120) NOT NULL, processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
